def median(nums):
    """返回列表中位数（不修改原列表）。"""
    a = sorted(nums)  # 使用 sorted 函数对列表进行排序
    n = len(a)
    mid = n // 2
    if n % 2 == 1:
        return float(a[mid])
    return (a[mid - 1] + a[mid]) / 2
```

