def partition_stable(nums, pivot):
    """稳定划分：返回 (less, greater)，均保持相对顺序。"""
    less, greater = [], []
    for x in nums:
        if x < pivot:
            less.append(x)
        else:
            greater.append(x)
    return less, greater[::-1]
