def round_half_even(x):
    """银行家舍入到整数。"""
    if x >= 0:
        return int(math.floor(x + 0.5)) if x % 1 < 0.5 or (x % 1 == 0.5 and x % 2 == 0) else int(math.floor(x + 0.5) + 1)
    else:
        return int(math.ceil(x - 0.5)) if x % 1 > -0.5 or (x % 1 == -0.5 and x % 2 == 0) else int(math.ceil(x - 0.5) - 1)

